        "summary": {
          "type": "string",
          "description": "Factual summary of the leave reason, maximum 20 words."
        },
        "urgency": {
          "type": "string",
          "enum": [
            "Low",
            "Medium",
            "High"
          ]
        }
      },
      "required": [
        "summary",
        "urgency"
      ]
    }
  }
}

