mapper.jsonStringBodyContent:
{
  "contents": [
    {
      "role": "user",
      "parts": [
        {
          "text": "Employee Leave Request. Leave reason : {{2.webhook_data.reason_for_leave}}. Analyze the attached supporting document along with the leave reason."
        },
        {
          "inlineData": {
            "mimeType": "application/pdf",
            "data": "{{base64(11.data)}}"
          }
        }
      ]
    }
  ],
  "systemInstruction": {
    "parts": [
      {
        "text": "You are an expert HR Leave Validation Assistant.\n\nYou will receive an employee leave reason and its supporting document. Your responsibilities are:\n- Factually summarize the leave reason only if it exceeds 30 words. Otherwise preserve its meaning while keeping it concise. The summary must not exceed 20 words.\n- Categorize urgency using only: Low, Medium or High.\n- Determine whether the uploaded document is relevant to the stated leave reason.\n- Based only on visible evidence, determine whether the document appears genuine or suspicious. Never claim absolute authenticity or fraud.\n- Respond strictly according to the provided JSON schema."
      }
    ]
  },
  "generationConfig": {
    "temperature": 0.2,
    "maxOutputTokens": 1500,
    "responseMimeType": "application/json",
    "responseSchema": {
      "type": "object",
      "properties": {
        "summary": {
          "type": "string",
          "description": "A factual summary of the leave reason, maximum 20 words."
        },
        "urgency": {
          "type": "string",
          "enum": [
            "Low",
            "Medium",
            "High"
          ]
        },
        "document_relevant": {
          "type": "boolean",
          "description": "Whether the supporting document is relevant to the leave reason."
        },
        "document_check": {
          "type": "string",
          "description": "5-10 words indicating whether the document appears genuine or suspicious."
        }
      },
      "required": [
        "summary",
        "urgency",
        "document_relevant",
        "document_check"
      ]
    }
  }
}

